sysauto_script.script:
(function() {
    // === Fetch Access Token ===
    var tokenGR = new GlideRecord("u_cisco_secure_access_token");
    tokenGR.orderByDesc("sys_created_on");
    tokenGR.setLimit(1);
    tokenGR.query();

    if (!tokenGR.next()) {
        gs.error("No access token found");
        return;
    }

    var accessToken = tokenGR.getValue("u_access_token");
    if (!accessToken) {
        gs.error("Access token is empty");
        return;
    }

    // === Query u_destination_list where u_list_id is empty ===
    var gr = new GlideRecord("u_cisco_secure_access_destination_list");
    gr.addNullQuery("u_list_id");
    gr.query();

    while (gr.next()) {
        var destName = gr.getValue("u_list_name");

        try {
            // === Call API (get all, then filter manually) ===
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint("https://api.sse.cisco.com/policies/v2/destinationlists");
            r.setHttpMethod("GET");
            r.setRequestHeader("Authorization", "Bearer " + accessToken);

            // get more results so we can find the correct match
            r.setQueryParameter("limit", "50");  
            r.setQueryParameter("page", "1");

            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();

            if (status == 200) {
                var parsed = JSON.parse(body);

                if (parsed.data && parsed.data.length > 0) {
                    var foundId = null;

                    for (var i = 0; i < parsed.data.length; i++) {
                        var item = parsed.data[i];

                        // Compare names (case-insensitive, trimmed)
                        if (item.name && item.name.toLowerCase().trim() === destName.toLowerCase().trim()) {
                            foundId = item.id;
                            break;
                        }
                    }

                    if (foundId) {
    // Store clean ID (remove commas)
    gr.u_list_id = String(foundId).replace(/,/g, "");

    // Store destination count if available
    if (item.meta && item.meta.destinationCount !== undefined) {
        gr.u_count = item.meta.destinationCount;
    }

    gr.update();
    gs.info("Updated destination '" + destName +
            "' with ID: " + foundId +
            " | Count: " + gr.u_count);
} else {
    gs.warn("No exact match found for: " + destName);
}

                } else {
                    gs.warn("API returned empty data for: " + destName);
                }
            } else {
                gs.error("API call failed for " + destName + " | Status: " + status + " | Body: " + body);
            }

        } catch (e) {
            gs.error("Exception while fetching ID for " + destName + " | " + (e.message || e.toString()));
        }
    }
})();
